{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_26",
      "quote": "Our systematic review and meta-analysis suggest that MSCs are a promising treatment for COVID-19, although the certainty of this effect is limited by the small number of studies and modest numbers of patients enrolled, as well as substantial heterogeneity between studies in terms of study design, characterization of MSC products and outcome reporting.",
      "reason": "The manuscript describes the current state of knowledge (MSCs look promising) and important uncertainties/limitations (small number of studies, modest patient numbers, substantial heterogeneity, inconsistent outcome reporting)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Background: Mesenchymal stem/stromal cells (MSCs) and their secreted products are a promising therapy for COVID-19 given their immunomodulatory and tissue repair capabilities. Many small studies were launched at the onset of the pandemic, and repeated meta-analysis is critical to obtain timely and suf fi cient statistical power to determine ef fi cacy.",
      "reason": "The abstract explicitly explains the need for the review: many small studies exist and repeated meta-analysis is needed to gain sufficient power and timely evidence."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_26",
      "quote": "Although this initial number of published studies identi fi ed in our search is relatively small, many registered clinical trials dealing with the use of MSC-based products as a therapeutic intervention for COVID-19 were identi fi ed in a scoping review performed by our group [31].",
      "reason": "The authors cite a prior scoping review by their group, indicating related prior work, but they do not explicitly discuss existing similar systematic reviews or explain how the current review updates or differs from prior systematic reviews; thus partial evidence for this item."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_26",
      "quote": "IL-6 levels have received signi fi cant attention as a mediator of damaging in fl ammation in COVID-19... Our analysis identi fi ed that MSCs lowered IL-6 levels. ... MSCs and their secreted factors may also support the regeneration of tissues damaged by the cytokine storm through release of growth factors including hepatocyte growth factor, keratinocyte growth factor and vascular endothelial growth factor [56,57]. Thus, the pleiotropic anti-in fl ammatory and regenerative effects of MSCs may point to several potential mechanisms by which MSCs exert their apparent bene fi cial effect.",
      "reason": "The manuscript describes proposed mechanisms of action for MSCs (immunomodulation, lowering IL-6, secretion of anti-inflammatory cytokines and growth factors, regenerative effects)."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found of a logic model or diagram showing hypothesised relationships between intervention components and outcomes; tables and text describe mechanisms but do not present a logic model."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
