  "confidence": 86
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "All English-language, full-text, clinical studies examining the use of MSCs or their secretome (MSC-EVs, MSC-CM) as a therapeutic intervention for COVID-19 were included. Studies could be single armed (uncontrolled) or have a comparator or control groups (controlled). For the controlled studies, all randomization methods were considered acceptable (randomized, pseudo-randomized, and nonrandomized). Studies published in languages other than English, review articles, commentaries, editorials, letters, case reports, conference abstracts, unpublished gray literature and other study types (in vitro studies, preclinical animal studies, etc. ) were excluded. All symptomatic or asymptomatic patients with confirmed SARS-CoV-2 infection (quantitative RT-PCR, antibody assay, etc. ) were included. MSCs derived from any known applicable tissue source (bone marrow, adipose tissue, umbilical cord, dental pulp, placenta, etc. ) were acceptable. MSCs could be obtained from syngeneic, allogeneic or xenogeneic tissues. All routes of MSC/secretome administration were acceptable (intravenous injection, aerosol inhalation, intramuscular injection, etc. ). MSC-based products could also be administered along with other therapeutic agents (antivirals, anti-cytokine drugs, immunomodulatory agents, etc. ). Studies exclusively investigating other non-MSC-based therapeutics were excluded.",
      "reason": "The eligibility section specifies study designs, language, excluded study types, patient inclusion criteria, acceptable MSC sources, routes of administration, and inclusion of single-arm and controlled studies, covering study characteristics used to determine eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "All English-language, full-text, clinical studies ... were included. ... Studies published in languages other than English, review articles, commentaries, editorials, letters, case reports, conference abstracts, unpublished gray literature and other study types ... were excluded.",
      "reason": "Report characteristics (language: English-only; publication/report status: full-text only, excluding conference abstracts and unpublished gray literature) are explicitly stated."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No text explicitly distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported; retrieved evidence does not address this distinction."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "For dichotomous outcomes, risk ratios (RRs) were calculated to determine the risk of death between the control and experimental groups at study endpoint. For continuous outcomes, the standardized mean difference (SMD) between control and experimental groups was calculated using random effects meta-analyses. ... Meta-analysis was performed only when three or more controlled studies reported on the same outcome.",
      "reason": "The methods define groups used in syntheses (control vs experimental) and link these to the comparisons used for pooled analyses and criteria for conducting meta-analysis."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although some restrictions are listed (e.g., English-language, full-text, exclusion of certain article types), no rationale explaining why these notable restrictions were applied is provided in the retrieved evidence."
    }
  ],
  "confidence": 80
}

